1	package agentusage
2	
3	import (
4		"reflect"
5		"strings"
6		"testing"
7	)
8	
9	type seen struct {
10		Line string
11		Off  int64
12	}
13	
14	func collect(t *testing.T, in string, max int) ([]seen, scanResult) {
15		t.Helper()
16		var got []seen
17		res, err := scanLines(strings.NewReader(in), max, func(line []byte, off int64) {
18			got = append(got, seen{string(line), off}) // copy: line is reused
19		})
20		if err != nil {
21			t.Fatalf("scanLines error: %v", err)
22		}
23		return got, res
24	}
25	
26	func TestScanLines(t *testing.T) {
27		tests := []struct {
28			name      string
29			in        string
30			max       int
31			want      []seen
32			consumed  int64
33			oversized int
34			tail      string
35		}{
36			{"empty input", "", 16, nil, 0, 0, ""},
37			{"two complete lines", "a\nb\n", 16, []seen{{"a", 0}, {"b", 2}}, 4, 0, ""},
38			{"trailing partial line", "a\nb", 16, []seen{{"a", 0}}, 2, 0, "b"},
39			{"only a partial line", "abc", 16, nil, 0, 0, "abc"},
40			{"blank lines ignored", "a\n\n\nb\n", 16, []seen{{"a", 0}, {"b", 4}}, 6, 0, ""},
41			{"crlf tolerated", "a\r\nbc\r\n", 16, []seen{{"a", 0}, {"bc", 3}}, 7, 0, ""},
42			{"cr-only line is blank", "a\n\r\nb\n", 16, []seen{{"a", 0}, {"b", 4}}, 6, 0, ""},
43			{"offsets with varied lengths", "abc\nde\nf\n", 16, []seen{{"abc", 0}, {"de", 4}, {"f", 7}}, 9, 0, ""},
44			{"exactly max is read", strings.Repeat("x", 16) + "\nok\n", 16, []seen{{strings.Repeat("x", 16), 0}, {"ok", 17}}, 20, 0, ""},
45			{"max+1 is skipped, next read", strings.Repeat("x", 17) + "\nok\n", 16, []seen{{"ok", 18}}, 21, 1, ""},
46			{"several oversized lines", strings.Repeat("y", 40) + "\n" + strings.Repeat("z", 100) + "\nok\n", 16, []seen{{"ok", 142}}, 145, 2, ""},
47			{"oversized then partial tail", strings.Repeat("x", 20) + "\nab", 16, nil, 21, 1, "ab"},
48		}
49		for _, tt := range tests {
50			t.Run(tt.name, func(t *testing.T) {
51				got, res := collect(t, tt.in, tt.max)
52				if !reflect.DeepEqual(got, tt.want) {
53					t.Errorf("lines = %v, want %v", got, tt.want)
54				}
55				if res.Consumed != tt.consumed {
56					t.Errorf("Consumed = %d, want %d", res.Consumed, tt.consumed)
57				}
58				if res.Oversized != tt.oversized {
59					t.Errorf("Oversized = %d, want %d", res.Oversized, tt.oversized)
60				}
61				if string(res.Tail) != tt.tail {
62					t.Errorf("Tail = %q, want %q", res.Tail, tt.tail)
63				}
64			})
65		}
66	}
67	
68	func TestScanLinesLongerThanReaderBuffer(t *testing.T) {
69		// A line larger than bufio's default 4 KiB buffer must be reassembled
70		// when under max and skipped when over it.
71		long := strings.Repeat("a", 10_000)
72		got, res := collect(t, long+"\nnext\n", 20_000)
73		want := []seen{{long, 0}, {"next", 10_001}}
74		if !reflect.DeepEqual(got, want) {
75			t.Errorf("under max: got %d lines, want %v", len(got), []string{"long", "next"})
76		}
77		if res.Oversized != 0 || res.Consumed != 10_006 {
78			t.Errorf("under max: %+v", res)
79		}
80	
81		got, res = collect(t, long+"\nnext\n", 9_999)
82		want = []seen{{"next", 10_001}}
83		if !reflect.DeepEqual(got, want) {
84			t.Errorf("over max: got %v, want %v", got, want)
85		}
86		if res.Oversized != 1 || res.Consumed != 10_006 {
87			t.Errorf("over max: %+v", res)
88		}
89	}
90	
91	func TestMaxLineBytes(t *testing.T) {
92		if MaxLineBytes != 4<<20 {
93			t.Errorf("MaxLineBytes = %d, want %d", MaxLineBytes, 4<<20)
94		}
95	}
96	
97	func TestScanLinesOversizedWithoutNewline(t *testing.T) {
98		// An over-long final line with no newline is neither kept in Tail nor
99		// counted: it may never be completed.
100		in := "ok\n" + strings.Repeat("x", 100_000)
101		got, res := collect(t, in, 16)
102		if want := []seen{{"ok", 0}}; !reflect.DeepEqual(got, want) {
103			t.Errorf("lines = %v, want %v", got, want)
104		}
105		if res.Consumed != 3 || res.Oversized != 0 || len(res.Tail) != 0 {
106			t.Errorf("result = %+v", res)
107		}
108	}
109	
110	func TestScanLinesCRLFAtMax(t *testing.T) {
111		got, res := collect(t, strings.Repeat("x", 16)+"\r\n", 16)
112		if len(got) != 1 || res.Oversized != 0 {
113			t.Errorf("got %v, %+v", got, res)
114		}
115	}
116

